styles:
@layer components {
  .seg-replay { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; color: var(--fg-subtle); transition: color 0.15s, background-color 0.15s; }
  .seg-replay:hover { color: var(--fg); background: var(--bg-inset); }
  .seg-track { position: relative; }
  .seg-sparks { position: absolute; left: -8px; top: -22px; width: calc(100% + 16px); height: calc(100% + 32px); pointer-events: none; }
  .seg-bar { position: relative; height: 56px; overflow: hidden; border-radius: 8px; background: repeating-linear-gradient(-45deg,var(--line) 0 1px,transparent 1px 6px),var(--bg-sunken); box-shadow: 0 0 0 1px var(--line-strong) inset; }
  .seg-layer, .seg-marks { position: absolute; inset: 0px; }
  .seg-fill { position: absolute; top: 0px; bottom: 0px; background: linear-gradient(180deg,color-mix(in oklch,var(--accent) 88%,white),var(--accent)); box-shadow: -1px 0 color-mix(in oklch,var(--bg) 70%,transparent) inset; }
  .seg-head { position: absolute; top: -2px; bottom: -2px; width: 2px; margin-left: -1px; background: transparent; }
  .seg-head.is-active { background: var(--cyan); box-shadow: 0 0 10px 1px var(--cyan); }
  .seg-head.is-active.is-slow { background: var(--warn); box-shadow: 0 0 10px 1px var(--warn); }
  .seg-mark { position: absolute; top: 0px; bottom: 0px; width: 1px; background: var(--fg); opacity: 0; animation: seg-mark 1.4s var(--ease-out); }
  @keyframes seg-mark { 
  0% { opacity: 0.9; box-shadow: 0 0 0 3px color-mix(in oklch,var(--fg) 25%,transparent); }
  100% { opacity: 0; }
}
  .seg-worker { display: flex; flex-direction: column; gap: 6px; padding: 8px 9px; background: var(--bg-elev); transition: background-color 0.3s; }
  .seg-meter { position: relative; height: 3px; overflow: hidden; border-radius: 9px; background: var(--bg-inset); }
  .seg-meter i { position: absolute; inset: 0px; transform-origin: left center; transform: scaleX(var(--level, 0)); background: var(--accent); transition: transform 0.2s linear; }
  .seg-worker[data-state="slow"] .seg-meter i { background: var(--warn); }
  .seg-worker[data-state="idle"] .mono { opacity: 0.5; }
  .seg-key { display: inline-block; width: 12px; height: 8px; border-radius: 2px; }
  .seg-key-done { background: var(--accent); }
  .seg-key-head { width: 2px; height: 12px; background: var(--cyan); box-shadow: 0 0 6px var(--cyan); }
  .seg-key-split { width: 1px; height: 12px; background: var(--fg); }
}
